function updatePlan(){const vals=Object.values(saved),review=vals.filter(x=>x.status==='review').length;let title,text,page='lexicon';if(review>=5){title='Revisit your difficult vocabulary.';text=`You have ${review} saved words marked for review. A focused flashcard session is the best next step.`;page='flashcards'}else if(!activity.practice.length){title='Test active recall.';text='There is no recent practice session yet. Try five mixed questions.';page='practice'}else if(!activity.cases.length){title='Move from vocabulary to reasoning.';text='Try one Public Health Case and use the terminology in context.';page='cases'}else if(!activity.comm.length){title='Practise communicating evidence.';text='Use one Communication Lab task to turn methods and data into clear professional English.';page='communication'}else if(!activity.group.length){title='Use your English collaboratively.';text='Try one Group Activity mission: analyse the evidence, negotiate priorities and deliver a 90-second briefing.';page='groupactivity'}else if(!activity.test.length){title='Check your overall progress.';text='You have practised vocabulary and applied tasks. Take the 24-question check-up to identify your next revision target.';page='test'}else if((activity.pron||0)<5){title='Add a short pronunciation workout.';text='Practise five high-value public-health terms for stress, rhythm and intelligibility.';page='pronunciation'}else{title='Keep building your specialist vocabulary.';text='Return to the lexicon, save useful new terms and revisit them in context.';page='lexicon'}$('#planTitle').textContent=title;$('#planText').textContent=text;$('#planAction').onclick=()=>showPage(page);$('#continueLearningTitle').textContent=title;$('#continueLearningText').textContent=text;$('#continueLearningAction').onclick=()=>showPage(page)}

