let testDeck=[],ti=0,tscore=0,testWrong=[];
function buildTest(){const chapterBuckets=Object.keys(CHAPTERS).flatMap(ch=>shuffle(TERMS.filter(t=>String(t.chapter)===ch)).slice(0,2));const extras=shuffle(TERMS.filter(t=>!chapterBuckets.includes(t))).slice(0,4);return shuffle([...chapterBuckets,...extras]).slice(0,24)}
function renderTest(){if(ti>=testDeck.length){activity.test.push({score:tscore,total:testDeck.length,date:Date.now()});testWrong.forEach(t=>{saved[t.word]=saved[t.word]||{};saved[t.word].status='review'});saveState();$('#testBox').innerHTML=`<div class="test-score"><h3>Check-up complete</h3><div class="big">${tscore}/${testDeck.length}</div><p>${tscore>=20?'Strong result. Keep using the Communication Lab and cases.':tscore>=15?'Solid base. Review the missed terms, then try again later.':'Use the missed terms as a focused revision deck.'}</p><button onclick="showPage('notebook')">Review saved words</button> <button class="primary-action" onclick="startTestRun()">Try another check-up</button></div>`;return}const t=testDeck[ti],mode=ti%3===0?'french':'definition',q=makeQ(t,mode);$('#testBox').innerHTML=`<article class="test-question"><span class="eyebrow">Question ${ti+1} / ${testDeck.length}</span><h3>${esc(q.prompt)}</h3><div class="option-grid">${q.opts.map(o=>`<button data-test-answer="${esc(o)}">${esc(o)}</button>`).join('')}</div><div id="testFeedback"></div></article>`;$$('[data-test-answer]').forEach(b=>b.onclick=()=>{const ok=b.dataset.testAnswer===q.answer;if(ok)tscore++;else testWrong.push(t);b.classList.add(ok?'correct':'wrong');$$('[data-test-answer]').forEach(x=>{if(x.dataset.testAnswer===q.answer)x.classList.add('correct');x.disabled=true});$('#testFeedback').innerHTML=`<div class="feedback"><strong>${ok?'Correct.':'Answer: '+esc(q.answer)}</strong><br><button id="nextTest">Next →</button></div>`;$('#nextTest').onclick=()=>{ti++;renderTest()}})}
function startTestRun(){testDeck=buildTest();ti=0;tscore=0;testWrong=[];renderTest()}window.startTestRun=startTestRun;$('#startTest').onclick=startTestRun;

