let groupSession1=store.get('group_session1',{step:0,choices:[],scores:{...SESSION1_BASE_SCORES},outcome:null,completed:false});
function normaliseGroupSession1(){if(!groupSession1||typeof groupSession1!=='object')groupSession1={};if(!Array.isArray(groupSession1.choices))groupSession1.choices=[];if(typeof groupSession1.step!=='number'||groupSession1.step<0)groupSession1.step=0;const scores=groupSession1.scores||{};groupSession1.scores={access:Number.isFinite(scores.access)?scores.access:SESSION1_BASE_SCORES.access,equity:Number.isFinite(scores.equity)?scores.equity:SESSION1_BASE_SCORES.equity,innovation:Number.isFinite(scores.innovation)?scores.innovation:SESSION1_BASE_SCORES.innovation,sustainability:Number.isFinite(scores.sustainability)?scores.sustainability:SESSION1_BASE_SCORES.sustainability};groupSession1.outcome=groupSession1.outcome&&typeof groupSession1.outcome==='object'?groupSession1.outcome:null;groupSession1.completed=Boolean(groupSession1.completed);if(groupSession1.step>SESSION1_STEPS.length)groupSession1.step=SESSION1_STEPS.length}
function saveGroupSession1(){store.set('group_session1',groupSession1)}
function resetGroupSession1(){groupSession1={step:0,choices:[],scores:{...SESSION1_BASE_SCORES},outcome:null,completed:false};saveGroupSession1();renderSession1Welcome()}
function clampGroupScore(v){return Math.max(0,Math.min(100,v))}
function scoreDeltaText(v){return v>0?`+${v}`:String(v)}
function groupDecisionCode(){return groupSession1.choices.length?groupSession1.choices.join('-'):'—'}
function buildGroupScoreBoard(scores){return `<div class="group-score-board">${Object.entries(SESSION1_SCORE_LABELS).map(([key,label])=>`<div class="group-score-row"><div class="group-score-label">${label}</div><div class="group-score-bar"><div class="group-score-fill" style="width:${scores[key]}%"></div></div><div class="group-score-value">${scores[key]}</div></div>`).join('')}</div>`}
function buildImpactPills(effect){return Object.entries(effect).map(([key,val])=>`<span class="group-impact-pill ${val>0?'positive':val<0?'negative':'neutral'}">${SESSION1_SCORE_LABELS[key]} ${scoreDeltaText(val)}</span>`).join('')}
function session1Option(stepIndex,choiceId){const step=SESSION1_STEPS[stepIndex];return step?step.options.find(o=>o.id===choiceId):null}
function session1SummaryCards(){return groupSession1.choices.map((choiceId,index)=>{const step=SESSION1_STEPS[index],opt=session1Option(index,choiceId);return `<article class="group-summary-card"><span class="eyebrow">${esc(step.title)}</span><h4>${esc(opt.id+'. '+opt.title)}</h4><p>${esc(opt.text)}</p></article>`}).join('')}
function session1Profile(){const s=groupSession1.scores;if(s.access>=82&&s.equity>=82&&s.sustainability<58)return{title:'The ambitious access advocate',icon:'🌍',text:'Your plan strongly improves access and equity, but long-term financial or logistical stability remains fragile.'};if(s.innovation>=82&&s.access<60)return{title:'The innovation-first strategist',icon:'💼',text:'You protected innovation and industry confidence, but too many patients remain excluded from treatment.'};if(s.sustainability>=80&&s.access>=70&&s.equity>=70)return{title:'The balanced system builder',icon:'🏗️',text:'Your agreement combines access, fairness and feasibility in a relatively stable way.'};if(s.equity>=84)return{title:'The equity champion',icon:'⚖️',text:'You consistently prioritised populations with the greatest need and reduced unfair inequalities.'};if(s.access>=84)return{title:'The emergency responder',icon:'🚑',text:'You focused strongly on rapid expansion of access, especially in crisis settings.'};const best=Object.entries(s).sort((a,b)=>b[1]-a[1])[0][0];if(best==='sustainability')return{title:'The long-term planner',icon:'♻️',text:'Your plan emphasises durability, delivery capacity and the ability to keep the agreement working over time.'};if(best==='innovation')return{title:'The market balancer',icon:'🔬',text:'Your decisions aimed to preserve the conditions needed for future research and production.'};return{title:'The pragmatic committee',icon:'🧠',text:'Your committee tried to balance competing priorities and make a workable global agreement.'}}
function ensureSession1Completed(){if(!activity.group.includes(SESSION1_ACTIVITY_ID)){activity.group=[...new Set([...(activity.group||[]),SESSION1_ACTIVITY_ID])];saveState()}}
function renderSession1Welcome(){normaliseGroupSession1();const resume=groupSession1.choices.length&&!groupSession1.completed;const completed=groupSession1.completed;$('#groupMissionSelect').value='session1';$('#groupMissionWorkspace').innerHTML=`<article><div class="group-sim-intro"><div class="group-sim-card"><span class="eyebrow">Session 1 mission</span><h3>Design a global access agreement for Novirex.</h3><p>You will make six decisions about allocation, price, patents, royalties, manufacturing and emergency response.</p><ul class="group-steps"><li><strong>Read before you click.</strong> The option order is fixed.</li><li><strong>Discuss every choice as a team.</strong> There is no single perfect answer.</li><li><strong>Read the consequence after each decision.</strong> Your four scores will change.</li><li><strong>Use your final decision code in your briefing.</strong></li></ul><div class="session-launch-actions"><button class="primary-action" id="startSession1Btn">${completed?'↻ Start again':resume?'▶ Resume simulation':'▶ Start simulation'}</button><button id="resetSession1Btn">Reset session</button></div></div><div class="group-sim-card"><span class="eyebrow">Scoring system</span><h4>Your four targets</h4><p><strong>Access</strong> = can enough people obtain the medicine?<br><strong>Equity</strong> = are the people with the greatest need protected?<br><strong>Innovation</strong> = does the agreement preserve incentives for research?<br><strong>Sustainability</strong> = can the system work over time?</p><div class="group-decision-code">Decision code: ${esc(groupDecisionCode())}</div>${buildGroupScoreBoard(groupSession1.scores)}</div></div></article>`;$('#startSession1Btn').onclick=()=>{if(completed){groupSession1={step:0,choices:[],scores:{...SESSION1_BASE_SCORES},outcome:null,completed:false};saveGroupSession1()}startSession1Flow()};$('#resetSession1Btn').onclick=()=>{resetGroupSession1()};$('#groupMissionWorkspace').scrollIntoView({behavior:scrollBehavior(),block:'start'})}
function startSession1Flow(){normaliseGroupSession1();groupSession1.completed=false;if(groupSession1.step>=SESSION1_STEPS.length){groupSession1.step=0;groupSession1.choices=[];groupSession1.scores={...SESSION1_BASE_SCORES};groupSession1.outcome=null}saveGroupSession1();renderSession1Step()}
function renderSession1Step(){normaliseGroupSession1();if(groupSession1.completed||groupSession1.step>=SESSION1_STEPS.length){renderSession1Result();return}if(groupSession1.outcome){renderSession1Outcome();return}const step=SESSION1_STEPS[groupSession1.step];$('#groupMissionWorkspace').innerHTML=`<article><div class="group-step-meta"><span class="eyebrow">${esc(step.title)}</span><div class="group-decision-code">Decision code: ${esc(groupDecisionCode())}</div></div><h3>${esc(step.question)}</h3><p>${esc(step.note)}</p>${buildGroupScoreBoard(groupSession1.scores)}<div class="group-choice-grid">${step.options.map(o=>`<button type="button" class="group-choice-card" data-group-choice="${o.id}"><span class="choice-letter">${o.id}</span><strong>${esc(o.title)}</strong><p>${esc(o.text)}</p></button>`).join('')}</div><div class="group-step-actions"><button id="confirmGroupChoice" class="primary-action" disabled>Confirm this group choice</button><button id="backToSession1Home">Back to Session 1 overview</button></div><div id="groupChoiceHint" class="fiction-note">Discuss the options first, then confirm one shared answer for the team.</div></article>`;let selected=null;$$('[data-group-choice]').forEach(btn=>btn.onclick=()=>{selected=btn.dataset.groupChoice;$$('[data-group-choice]').forEach(x=>x.classList.toggle('selected',x===btn));$('#confirmGroupChoice').disabled=false;$('#groupChoiceHint').textContent=`Selected option: ${selected}. Confirm when the whole team agrees.`});$('#confirmGroupChoice').onclick=()=>{if(!selected)return;applySession1Choice(selected)};$('#backToSession1Home').onclick=renderSession1Welcome;$('#groupMissionWorkspace').scrollIntoView({behavior:scrollBehavior(),block:'start'})}
function applySession1Choice(choiceId){const step=SESSION1_STEPS[groupSession1.step],option=step.options.find(o=>o.id===choiceId);if(!option)return;for(const [key,val] of Object.entries(option.effect))groupSession1.scores[key]=clampGroupScore(groupSession1.scores[key]+val);groupSession1.choices[groupSession1.step]=choiceId;groupSession1.outcome={stepIndex:groupSession1.step,choiceId,consequence:option.consequence,effect:option.effect,title:option.title};saveGroupSession1();renderSession1Outcome()}
function renderSession1Outcome(){const result=groupSession1.outcome;if(!result){renderSession1Step();return}const step=SESSION1_STEPS[result.stepIndex],option=session1Option(result.stepIndex,result.choiceId);$('#groupMissionWorkspace').innerHTML=`<article><div class="group-step-meta"><span class="eyebrow">${esc(step.title)} · consequence</span><div class="group-decision-code">Decision code: ${esc(groupDecisionCode())}</div></div><h3>You chose ${esc(option.id+'. '+option.title)}</h3>${buildGroupScoreBoard(groupSession1.scores)}<div class="group-consequence-box"><strong>What happens next?</strong><p>${esc(option.consequence)}</p><div class="group-impact-pills">${buildImpactPills(option.effect)}</div></div><div class="group-step-actions"><button id="continueSession1" class="primary-action">${result.stepIndex===SESSION1_STEPS.length-1?'See final result →':'Continue to the next decision →'}</button><button id="restartSession1Mid">Restart session</button></div></article>`;$('#continueSession1').onclick=()=>{groupSession1.step=result.stepIndex+1;groupSession1.outcome=null;if(groupSession1.step>=SESSION1_STEPS.length){groupSession1.completed=true;ensureSession1Completed()}saveGroupSession1();groupSession1.completed?renderSession1Result():renderSession1Step()};$('#restartSession1Mid').onclick=()=>{resetGroupSession1()};$('#groupMissionWorkspace').scrollIntoView({behavior:scrollBehavior(),block:'start'})}
function renderSession1Result(){normaliseGroupSession1();groupSession1.completed=true;saveGroupSession1();ensureSession1Completed();const profile=session1Profile();$('#groupMissionSelect').value='session1';$('#groupMissionWorkspace').innerHTML=`<article><div class="group-profile-banner"><div class="group-profile-icon" aria-hidden="true">${profile.icon}</div><div><span class="eyebrow">Session 1 complete</span><h3>${esc(profile.title)}</h3><p>${esc(profile.text)}</p></div></div><div class="group-result-box"><div class="group-step-meta"><strong>Final decision code</strong><div class="group-decision-code">${esc(groupDecisionCode())}</div></div>${buildGroupScoreBoard(groupSession1.scores)}</div><div class="group-summary-grid">${session1SummaryCards()}</div><div class="group-briefing-grid"><div class="group-sim-card"><span class="eyebrow">Final speaking task</span><h4>Your 90-second group briefing</h4><ol class="group-steps"><li>State your main priority.</li><li>Explain one difficult trade-off.</li><li>Use the decision code to justify your plan.</li><li>Say what you would monitor next.</li></ol><div class="group-vocab-badges">${SESSION1_VOCAB.map(v=>`<span class="badge">${esc(v)}</span>`).join('')}</div></div><div class="group-sim-card"><span class="eyebrow">Teacher support</span><h4>Possible briefing structure</h4><p>“Our committee designed a global access agreement for Novirex. Our main priority was … We chose … because … The most difficult trade-off was … On balance, we recommend … We would monitor … to assess the impact of the agreement.”</p><p><small>Two teams making the same choices will always obtain the same result on any device.</small></p></div></div><div class="group-step-actions"><button id="restartSession1Final" class="primary-action">↻ Play again</button><button id="returnSession1Home">Back to Session 1 overview</button></div></article>`;$('#restartSession1Final').onclick=()=>{groupSession1={step:0,choices:[],scores:{...SESSION1_BASE_SCORES},outcome:null,completed:false};saveGroupSession1();renderSession1Step()};$('#returnSession1Home').onclick=renderSession1Welcome;$('#groupMissionWorkspace').scrollIntoView({behavior:scrollBehavior(),block:'start'})}
function drawGroupRoles(){const size=+$('#groupSize').value||4;const roles=shuffle(SESSION1_ROLES);const assigned=size===3?[roles[0],roles[1],roles[2]+' + '+roles[3]]:roles.slice(0,4);$('#groupRoleDraw').hidden=false;$('#groupRoleDraw').innerHTML=`<h3>Role draw · ${size} students</h3><div class="role-pills">${assigned.map((r,i)=>`<span class="role-pill">Student ${i+1}: ${esc(r)}</span>`).join('')}</div><p class="fiction-note">If you are only three, the last student combines two roles.</p>`}
function openSession1FromCard(){renderSession1Welcome();const target=$('#groupMissionWorkspace');if(target)target.scrollIntoView({behavior:scrollBehavior(),block:'start'})}
function initSession1GroupActivity(){normaliseGroupSession1();const select=$('#groupMissionSelect');if(select)select.innerHTML='<option value="session1">Session 1 — Who Gets the Medicine?</option>';if($('#session1CardButton'))$('#session1CardButton').onclick=openSession1FromCard;if($('#openGroupMission'))$('#openGroupMission').onclick=openSession1FromCard;if($('#randomGroupMission'))$('#randomGroupMission').onclick=()=>{groupSession1={step:0,choices:[],scores:{...SESSION1_BASE_SCORES},outcome:null,completed:false};saveGroupSession1();renderSession1Step()};if($('#drawGroupRoles'))$('#drawGroupRoles').onclick=drawGroupRoles;renderSession1Welcome()}
initSession1GroupActivity();
